            auto [r, c] = q.front(); q.pop();
            if (board[r][c] != 'E') continue;
            int cnt = 0;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == 'M') cnt++;
            }
            if (cnt) board[r][c] = '0' + cnt;
            else {
                board[r][c] = 'B';
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] == 'E')
                        q.push({nr, nc});
                }
            }
        }
        return board;
    }
};

